diff --git a/repro/check.mjs b/repro/check.mjs
new file mode 100644
index 000000000..26dfb9cfd
--- /dev/null
+++ b/repro/check.mjs
@@ -0,0 +1,32 @@
+// Usage: node repro/check.mjs [file.ts]   (default: repro/inline-assertion.ts)
+// Exits 1 if the type alias `Test` in the file is not `{ prop1: "hello"; }`.
+import { createRequire } from "node:module";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+
+const here = path.dirname(fileURLToPath(import.meta.url));
+const require = createRequire(import.meta.url);
+const ts = require(process.env.TS_PATH ?? path.join(here, "..", "built", "local", "typescript.js"));
+
+const file = path.resolve(process.argv[2] ?? path.join(here, "inline-assertion.ts"));
+const program = ts.createProgram([file], { strict: true, noEmit: true, target: ts.ScriptTarget.ESNext });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+
+let alias;
+sf.forEachChild(function visit(n) {
+    if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") alias = n;
+});
+const type = checker.getTypeAtLocation(alias.name);
+const actual = checker.typeToString(type, undefined, ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias);
+const expected = `{ prop1: "hello"; }`;
+
+console.log(`typescript ${ts.version}`);
+console.log(`file:     ${path.relative(process.cwd(), file)}`);
+console.log(`expected: type Test = ${expected}`);
+console.log(`actual:   type Test = ${actual}`);
+if (actual !== expected) {
+    console.log("FAIL: Test is not the unwrapped type");
+    process.exit(1);
+}
+console.log("PASS");
diff --git a/repro/inline-assertion.ts b/repro/inline-assertion.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/inline-assertion.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
